"""A short, accessible project-matching game with useful next steps."""
from editorial import write_editorial_page
import shutil


def add(out, origin, pages):
    body='''<div class="wrap match-page"><div class="breadcrumb"><a href="/explore/">Tools &amp; discoveries</a><span>/</span>Who would you call?</div><header class="match-intro"><div class="eyebrow">THE WAZOOZIE QUICK PLAY</div><h1>Who would<br><em>you call?</em></h1><p>A house. A car. A few curveballs. Match six everyday projects to the right kind of help.</p><p class="match-small">No clock. No sign-up. Just a little neighborly know-how.</p></header><section class="match-board" aria-label="Project matching game"><div class="match-top"><span id="match-progress">Six projects. Make the call.</span><span id="match-score">0 points</span></div><progress id="match-meter" max="6" value="0" aria-label="Projects completed"></progress><div id="match-start"><img src="/assets/clay-family-porch.webp" width="1200" height="800" alt="Fictional clay-style family relaxing on a porch"><h2>Got a good instinct?</h2><p>Pick the right help for each project. Get it first try for 100 points. A miss? Have another go.</p><button class="btn primary" id="match-play" type="button">Let’s play</button></div><div id="match-round" hidden><img id="match-image" width="1200" height="800" alt=""><div class="match-round-copy"><p class="eyebrow" id="match-kicker"></p><h2 id="match-question" tabindex="-1"></h2><div id="match-choices" class="match-choices"></div><div id="match-feedback" role="status" aria-live="polite"></div><div class="match-round-actions"><a id="match-help" hidden>Find this kind of help</a><button class="btn primary" id="match-next" type="button" hidden>Next project</button></div></div></div><div id="match-finish" hidden><div class="match-medallion" aria-hidden="true">W.</div><h2 id="match-result" tabindex="-1"></h2><p id="match-summary"></p><div class="match-end-actions"><button class="btn primary" id="match-again" type="button">Play a fresh round</button><button class="btn outline" id="match-share" type="button">Copy my score to share</button><a href="/book/">Find someone for your real project →</a></div><p id="match-share-status" role="status"></p><a href="/good-call-club/">Ready for today’s five-question quiz? →</a></div><p class="match-caption">AI-created clay scenes · Fictional people and projects.</p></section><noscript><p>The game needs JavaScript. You can still <a href="/services/">browse home services</a>, <a href="/auto-mechanics/">find auto care</a> or <a href="/pricing-guide/">explore project costs</a>.</p></noscript><section class="match-after"><h2>Good instincts. Even better questions.</h2><p>For a real project, describe what you need and ask the business to confirm its services, coverage and availability.</p><a href="/project-kit/">Get your project ready →</a><a href="/pricing-guide/">Check the cost guide →</a></section></div>'''
    write_editorial_page(out,origin,pages,'/who-would-you-call/','Who Would You Call? Free Project Matching Game','Play Wazoozie’s free six-project matching game. Test your home, auto and local-service know-how, share your score and find a useful next step.',body)
    p=out/'who-would-you-call/index.html';s=p.read_text().replace('id="match-image" width="1200" height="800" alt=""','id="match-image" src="/assets/clay-family-porch.webp" width="1200" height="800" alt="Fictional clay-style home project scene"').replace('</head>','<link rel="stylesheet" href="/assets/home-match.css"></head>').replace('</body>','<script type="module" src="/assets/home-match.js"></script></body>');p.write_text(s)
    for name in ('home-match.css','home-match.js'):shutil.copy(out.parent/'assets'/name,out/'assets'/name)
    teaser='<aside class="match-teaser"><div><span class="eyebrow">A LITTLE PLAY. A GOOD INSTINCT.</span><h2>Who would you call?</h2><p>Six projects. A few curveballs. See how well you know who does what.</p></div><a class="btn primary" href="/who-would-you-call/">Play the quick challenge →</a></aside>'
    for route in ('','explore','good-call-club'):
        p=out/route/'index.html';s=p.read_text()
        if route=='':s=s.replace('<div class="front-door-categories',teaser+'<div class="front-door-categories',1)
        else:s=s.replace('</main>','<div class="wrap">'+teaser+'</div></main>',1)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/home-match.css"></head>',1);p.write_text(s)
